package com.tencent.weknora.storage;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.assertj.core.api.Assertions.*;

class LocalFileStoreTest {
    @TempDir Path temporary;LocalFileStore files;Path base;
    @BeforeEach void initialize(){base=temporary.resolve("files");files=new LocalFileStore(base,"",null,1024);}
    @Test void savesGoTenantKnowledgeLayoutAndIndependentCopy()throws Exception{byte[] bytes="source".getBytes();String path=files.saveFile(new ByteArrayInputStream(bytes),"a.tar.gz",1,"knowledge");assertThat(path).matches("local://1/knowledge/[0-9]+\\.gz");String copied=files.copy(path,1,"other");assertThat(copied).matches("local://1/other/[0-9]+\\.gz");assertThat(copied).isNotEqualTo(path);files.delete(path);try(var input=files.open(copied)){assertThat(input.readAllBytes()).isEqualTo(bytes);}assertThatThrownBy(()->files.open(path)).isInstanceOf(IOException.class);}
    @Test void bytesUseGoExportLayoutAndSafeBasename()throws Exception{String path=files.saveBytes(new byte[]{1,2},1,"nested/picture.png",true);assertThat(path).matches("local://1/exports/picture_[0-9]+\\.png");try(var input=files.open(path)){assertThat(input.readAllBytes()).containsExactly(1,2);}for(String name:new String[]{"","/","..","bad..png","a".repeat(256)})assertThatThrownBy(()->files.saveBytes(new byte[]{1},1,name,false)).isInstanceOf(IOException.class);}
    @Test void legacyCanonicalCleanedAbsoluteAndBasePrefixedAliasesResolve()throws Exception{String path=files.saveBytes(new byte[]{7},1,"a",false),relative=path.substring(8);for(String alias:List.of(path,"local:/"+relative,"storage://instance/"+path,"storage:/instance/local:/"+relative,base.resolve(relative).toString(),relative,base.toString().replaceFirst("^/","")+"/"+relative))try(var stream=files.open(alias)){assertThat(stream.readAllBytes()).containsExactly(7);}}
    @Test void boundedWritesCleanPartialFilesAndDoNotCloseCallerInput()throws Exception{var input=new ByteArrayInputStream(new byte[1025]){boolean closed;@Override public void close(){closed=true;}};assertThatThrownBy(()->files.saveFile(input,"a.bin",1,"doc")).isInstanceOf(IOException.class).hasMessageContaining("maximum");try(var walk=Files.walk(base)){assertThat(walk.filter(Files::isRegularFile)).isEmpty();}assertThat(input.closed).isFalse();}
    @Test void deniesTraversalCrossTenantNamespaceAndSymbolicAncestors()throws Exception{files.saveBytes(new byte[]{1},1,"a",false);Files.write(temporary.resolve("secret"),new byte[]{3});for(String path:List.of("local://../secret",temporary.resolve("secret").toString(),"local://1/../../secret"))assertThatThrownBy(()->files.open(path)).isInstanceOf(IOException.class);assertThatThrownBy(()->files.saveFile(new ByteArrayInputStream(new byte[]{2}),"a",1,"../2/doc")).isInstanceOf(IOException.class);Files.createSymbolicLink(base.resolve("1/link"),temporary);assertThatThrownBy(()->files.open("local://1/link/secret")).isInstanceOf(IOException.class);assertThatThrownBy(()->files.saveFile(new ByteArrayInputStream(new byte[]{2}),"a",1,"link/doc")).isInstanceOf(IOException.class);}
    @Test void connectivityRequiresExistingDirectoryAndDirectoriesAreNotObjects()throws Exception{assertThatThrownBy(files::checkConnectivity).isInstanceOf(IOException.class);String path=files.saveFile(new ByteArrayInputStream(new byte[0]),"/",1,"doc");assertThat(path).matches("local://1/doc/[0-9]+");files.checkConnectivity();assertThatThrownBy(()->files.open("local://1/doc")).isInstanceOf(IOException.class);}
    @Test void backendDecoratorScopesWritesRejectsForeignReadsAndPresignsScopedPath()throws Exception{var signer=new FileUrlSigner("migration-storage-test-key-32-bytes","");var local=new LocalFileStore(base,"https://files.test",signer,1024);var scoped=new BackendScopedFileStore(" instance ",local,signer,"https://files.test");String path=scoped.saveFile(new ByteArrayInputStream(new byte[]{1}),"a.png",1,"doc");assertThat(path).startsWith("storage://instance/local://1/doc/");try(var input=scoped.open(path)){assertThat(input.readAllBytes()).containsExactly(1);}String url=scoped.url(path);assertThat(url).contains("file_path=storage%3A%2F%2Finstance%2Flocal%3A%2F%2F1%2Fdoc%2F");assertThatThrownBy(()->scoped.open(path.replace("instance","other"))).isInstanceOf(IOException.class);assertThatThrownBy(()->new BackendScopedFileStore("",local,signer,"")).isInstanceOf(IllegalArgumentException.class);}
    @Test void signingFailureFallsBackToPhysicalPath()throws Exception{String path=files.saveBytes(new byte[]{1},1,"a",false);var missing=new LocalFileStore(base,"https://files.test",new FileUrlSigner("",""),1024);assertThat(missing.url(path)).isEqualTo(path);var malformed=new LocalFileStore(base,"http://[broken",new FileUrlSigner("migration-storage-test-key-32-bytes",""),1024);assertThat(malformed.url(path)).isEqualTo(path);}
}
